// Payments have no deleted_at of their own; a payment is hidden when its
// order is soft-deleted.
function liveOrderIds() {
  return new Promise((resolve, reject) => {
    query('orders', (o) => o.deleted_at === null,
      (err, rows) => (err ? reject(err) : resolve(new Set(rows.map((o) => o.id)))));
  });
}

function findLive(predicate) {
  return liveOrderIds().then((live) => new Promise((resolve, reject) => {
    query('payments', (p) => live.has(p.order_id) && predicate(p),
      (err, rows) => (err ? reject(err) : resolve(rows)));
  }));
}

export class PaymentRepository {
  findByOrder(orderId) {
    return findLive((p) => p.order_id === orderId);
  }

  findByOrders(orderIds) {
    const ids = new Set(orderIds);
    return findLive((p) => ids.has(p.order_id));
  }

  findUncaptured() {
    return findLive((p) => p.captured === false);
  }
}

